"""Nederlands — Koran (quran_001 … quran_080)."""

T = {
"quran_001": ("Wat is de naam van het eerste hoofdstuk (soera) van de Koran?", ["Al-Fatiha", "Al-Baqara", "Al-Ikhlas", "An-Nas"], "Al-Fatiha, «De Opening», is het eerste hoofdstuk van de Koran."),
"quran_002": ("Hoeveel hoofdstukken (soera's) bevat de Koran?", ["114", "99", "100", "120"], "De Koran bestaat uit 114 soera's."),
"quran_003": ("Wat is de langste soera van de Koran?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "Al-'Asr"], "Al-Baqara is de langste soera van de Koran, met 286 verzen."),
"quran_004": ("Wat is de kortste soera van de Koran?", ["Al-Kawthar", "Al-Ikhlas", "Al-'Asr", "An-Nasr"], "Al-Kawthar, met 3 verzen, is de kortste soera van de Koran."),
"quran_005": ("In welke taal werd de Koran geopenbaard?", ["Arabisch", "Aramees", "Hebreeuws", "Perzisch"], "De Koran zegt uitdrukkelijk dat hij in de Arabische taal is geopenbaard."),
"quran_006": ("Wat is de naam van de 19e soera, genoemd naar de moeder van Isa?", ["Maryam", "Yusuf", "Al-Kahf", "Ta-Ha"], "De 19e soera van de Koran heet Maryam, naar de moeder van de profeet Isa."),
"quran_007": ("Hoe heet een hoofdstuk van de Koran?", ["Een soera", "Een hadith", "Een juz'", "Een tafsir"], "De Koran is verdeeld in hoofdstukken die soera's worden genoemd."),
"quran_008": ("Hoe heet een vers van de Koran?", ["Een aya", "Een soera", "Een hadith", "Een ruku'"], "Elk vers van de Koran wordt een aya genoemd, wat «teken» betekent."),
"quran_009": ("Welke soera wordt verplicht gereciteerd in elke eenheid (rak'a) van het gebed?", ["Al-Fatiha", "Al-Ikhlas", "Al-Kawthar", "Al-Fil"], "Het reciteren van Al-Fatiha is een pijler van het gebed, overgeleverd in een authentieke hadith."),
"quran_010": ("Aan wie werd de Koran geopenbaard?", ["Aan de Profeet Muhammad ﷺ", "Aan de Profeet Musa", "Aan de Profeet Isa", "Aan de Profeet Dawud"], "De Koran werd geopenbaard aan de Profeet Muhammad ﷺ, via de engel Jibril."),
"quran_011": ("Hoe heet het beroemde vers 255 van soera Al-Baqara?", ["Ayat al-Kursi (het Troonvers)", "Ayat an-Nur", "Ayat as-Siyam", "Ayat ad-Dayn"], "Vers 2:255, Ayat al-Kursi, beschrijft Allahs grootheid: «Allah, er is geen god dan Hij, de Eeuwig Levende…»"),
"quran_012": ("Welke soera begint niet met «Bismillah ir-Rahman ir-Rahim»?", ["At-Tawba", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "At-Tawba (soera 9) is de enige soera die niet met de basmala opent."),
"quran_013": ("Wat is het onderwerp van het langste vers van de Koran (2:282)?", ["Het opschrijven van schulden", "De bedevaart", "Het vasten", "De erfenis"], "Het langste vers van de Koran leert schulden op te schrijven en getuigen te nemen: eerlijkheid wordt beschermd."),
"quran_014": ("Met welk woord beginnen de allereerste geopenbaarde verzen van de Koran?", ["Iqra' (Lees!)", "Qul (Zeg!)", "Sabbih (Verheerlijk!)", "Kutiba (Het is voorgeschreven)"], "De eerste geopenbaarde verzen beginnen met «Iqra'»: «Lees, in de naam van jouw Heer die schiep.»"),
"quran_015": ("Volgens de Koran is de Nacht van Al-Qadr beter dan hoeveel maanden?", ["Duizend maanden", "Honderd maanden", "Twaalf maanden", "Veertig maanden"], "«De Nacht van Al-Qadr is beter dan duizend maanden»: één nacht in de Ramadan die meer waard is dan een leven van aanbidding."),
"quran_016": ("Hoe heten de laatste twee soera's, Al-Falaq en An-Nas, die ter bescherming worden gereciteerd?", ["Al-Mu'awwidhatan (de twee beschermers)", "Az-Zahrawan", "Al-Mufassal", "As-Sab' at-Tiwal"], "Al-Falaq en An-Nas worden «al-mu'awwidhatan» genoemd: zij worden gereciteerd om Allahs bescherming te zoeken."),
"quran_017": ("In hoeveel delen (juz') is de Koran traditioneel verdeeld?", ["30", "10", "60", "114"], "De Koran is verdeeld in 30 juz', wat helpt hem in een maand uit te lezen, bijvoorbeeld tijdens de Ramadan."),
"quran_018": ("Hoeveel verzen bevat soera Al-Fatiha?", ["7", "3", "10", "14"], "Al-Fatiha heeft zeven verzen, gereciteerd in elke eenheid van het gebed."),
"quran_019": ("Welke soera is genoemd naar een metaal?", ["Al-Hadid (Het IJzer)", "An-Nur (Het Licht)", "Ar-Ra'd (De Donder)", "Ad-Dukhan (De Rook)"], "Soera 57 heet Al-Hadid: «Wij zonden het ijzer neer, waarin grote kracht is en voordelen voor de mensen.»"),
"quran_020": ("Welk verhaal noemt de Koran «het mooiste van de verhalen»?", ["Het verhaal van Yusuf", "Het verhaal van Nuh", "Het verhaal van de mensen van de grot", "Het verhaal van de olifant"], "«Wij vertellen jou het mooiste van de verhalen»: zo opent het verhaal van Yusuf."),
"quran_021": ("Hoeveel verzen bevat Al-Baqara, de langste soera?", ["286", "114", "200", "365"], "Al-Baqara heeft 286 verzen: de langste soera van de Koran."),
"quran_022": ("Welke korte soera verkondigt: «Zeg: Hij is Allah, de Ene»?", ["Al-Ikhlas", "Al-Falaq", "An-Nas", "Al-Kawthar"], "Al-Ikhlas verkondigt Allahs volmaakte eenheid in vier verzen."),
"quran_023": ("Over ongeveer hoeveel jaar werd de Koran geopenbaard?", ["23 jaar", "1 jaar", "10 jaar", "40 jaar"], "De Koran werd geleidelijk geopenbaard over ongeveer 23 jaar, in Mekka en daarna in Medina."),
"quran_024": ("Wat was volgens de Koran het eerste Huis dat voor de mensen werd gevestigd om Allah te aanbidden?", ["De Ka'ba, in Bakka (Mekka)", "De moskee van Quba", "Bayt al-Maqdis", "De moskee van de Profeet ﷺ"], "«Het eerste Huis dat voor de mensheid werd gevestigd is dat in Bakka, gezegend…»: de Ka'ba in Mekka."),
"quran_025": ("Welke soera is genoemd naar de olifant?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqara"], "Soera 105, Al-Fil («De Olifant»), herinnert aan het olifantenleger van Abraha, tegengehouden vóór Mekka."),
"quran_026": ("Soera An-Nahl is genoemd naar welk insect?", ["De bij", "De mier", "De spin", "De vlieg"], "An-Nahl betekent «de bijen»; daarin inspireert Allah de bij om haar woningen te bouwen (16:68)."),
"quran_027": ("Welke soera is genoemd naar de mier?", ["An-Naml", "An-Nahl", "Al-'Ankabut", "Al-An'am"], "An-Naml («De Mieren», soera 27) vertelt over de mier die haar soortgenoten waarschuwde toen het leger van Sulayman naderde."),
"quran_028": ("Waarmee vergelijkt de Koran in soera Al-'Ankabut degenen die beschermers naast Allah nemen?", ["Met een spin die een broos huis bouwt", "Met een bij die haar korf bouwt", "Met een mier die voedsel opslaat", "Met een hijgende hond"], "«Het zwakste van de huizen is het huis van de spin» (29:41), wat de soera haar naam geeft."),
"quran_029": ("Soera Al-Baqara is genoemd naar welk dier?", ["De koe", "De kameel", "Het paard", "Het schaap"], "Al-Baqara («De Koe») herinnert aan de koe die de Kinderen van Israël moesten offeren (2:67)."),
"quran_030": ("Wat betekent de titel van soera 6, Al-An'am?", ["Het vee", "De vogels", "De tuinen", "De sterren"], "Al-An'am betekent «het vee»; de soera weerlegt de verzonnen regels van de heidenen over vee."),
"quran_031": ("Welk vers wordt vele malen herhaald in soera Ar-Rahman?", ["«Welke van de gunsten van jullie Heer loochenen jullie?»", "«Allah is de Grootste»", "«Zeg: Hij is Allah, Eén»", "«Lof zij Allah»"], "Dit refrein («Fa-bi-ayyi ala'i rabbikuma tukadhdhiban») komt 31 keer voor in soera 55."),
"quran_032": ("Hoe lang sliepen de Mensen van de Grot volgens soera Al-Kahf?", ["Driehonderd jaar, plus negen", "Honderd jaar", "Veertig jaar", "Duizend jaar"], "«Zij verbleven driehonderd jaar in hun grot, en voegden er negen aan toe» (18:25)."),
"quran_033": ("Welk dier was bij de Mensen van de Grot?", ["Een hond", "Een kat", "Een ezel", "Een geit"], "«Hun hond strekte zijn voorpoten uit bij de ingang» (18:18)."),
"quran_034": ("Tegen welke volkeren bouwde Dhul-Qarnayn een barrière, volgens Al-Kahf?", ["Ya'juj en Ma'juj (Gog en Magog)", "'Ad en Thamud", "De Romeinen", "De Perzen"], "Een volk vroeg hem om bescherming tegen Ya'juj en Ma'juj; hij richtte een wal van ijzer en koper op (18:94-96)."),
"quran_035": ("Welk vers begint met «Allah is het Licht van de hemelen en de aarde»?", ["Het Lichtvers (An-Nur 24:35)", "Het Troonvers", "Het Schuldvers", "Het Grotvers"], "«Ayat an-Nur» vergelijkt Zijn licht met een nis waarin een lamp schijnt (24:35)."),
"quran_036": ("Welke soera staat volgens een hadith in al-Bukhari gelijk aan een derde van de Koran?", ["Al-Ikhlas", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "De Profeet ﷺ zei over «Qul huwa Allahu ahad» dat het «gelijk staat aan een derde van de Koran»."),
"quran_037": ("Welk vers noemde de Profeet ﷺ als het grootste van de Koran, volgens Sahih Muslim?", ["Het Troonvers (Ayat al-Kursi)", "Het eerste vers van Al-Fatiha", "Het laatste vers van Al-Baqara", "Het Lichtvers"], "Hij vroeg Ubayy ibn Ka'b welk vers het grootste was; Ubayy antwoordde Ayat al-Kursi, en de Profeet ﷺ feliciteerde hem."),
"quran_038": ("Welke vijand van de Profeet ﷺ wordt in soera Al-Masad bij naam genoemd?", ["Abu Lahab", "Abu Jahl", "Abu Sufyan", "Al-Walid"], "«Mogen de handen van Abu Lahab vergaan» (111:1): deze oom van de Profeet ﷺ bestreed hem openlijk."),
"quran_039": ("Hoe eindigt soera Al-Kafirun?", ["«Aan jullie jullie religie, en aan mij mijn religie»", "«Allah is de Grootste»", "«En niemand is aan Hem gelijk»", "«Tegen het kwaad van de afgunstige»"], "«Lakum dinukum wa liya din» (109:6) stelt de duidelijke scheiding tussen de islam en de afgoderij."),
"quran_040": ("Waarover gaat soera An-Nasr?", ["Over Allahs hulp en de mensen die in menigten de religie binnentreden", "Over de schepping van de hemel", "Over het vasten in de Ramadan", "Over het verhaal van Yusuf"], "«Wanneer Allahs hulp en de overwinning komen, en je de mensen in menigten Allahs religie ziet binnentreden» (110:1-2)."),
"quran_041": ("Wie wordt volgens soera Al-'Asr van verlies gered?", ["Zij die geloven, het goede doen en elkaar aansporen tot waarheid en geduld", "Zij die rijk zijn", "Zij die sterk zijn", "Zij die reizen"], "«De mens verkeert in verlies, behalve zij die geloven, goede daden verrichten en elkaar aansporen tot waarheid en tot geduld» (103:2-3)."),
"quran_042": ("Wat doet in soera Al-Ma'un «degene die het Oordeel loochent»?", ["Hij stoot de wees weg en spoort niet aan tot het voeden van de arme", "Hij vernielt moskeeën", "Hij weigert te reizen", "Hij liegt over zijn rijkdom"], "«Dat is degene die de wees wegstoot en niet aanspoort tot het voeden van de arme» (107:2-3)."),
"quran_043": ("Waaruit schiep Allah de mens volgens de eerste geopenbaarde verzen (Al-'Alaq)?", ["Uit een klonter ('alaq)", "Uit licht", "Uit vuur", "Uit wind"], "«Lees, in de naam van jouw Heer die schiep, die de mens schiep uit een klonter» (96:1-2)."),
"quran_044": ("Waarnaar verwijst de Koranische uitdrukking «de zeven vaak herhaalde verzen» (as-sab' al-mathani)?", ["Al-Fatiha", "De zeven langste soera's", "Ayat al-Kursi", "De laatste zeven verzen van de Koran"], "«Wij hebben jou zeven van de vaak herhaalde gegeven en de grootse Koran» (15:87): Al-Fatiha, gereciteerd in elke rak'a."),
"quran_045": ("Wat betekent «Al-Furqan», een van de namen van de Koran?", ["Het Onderscheid (tussen waarheid en leugen)", "Het Licht", "De Herinnering", "De Genezing"], "«Gezegend is Hij die de Furqan aan Zijn dienaar heeft neergezonden» (25:1): het Boek dat waarheid van leugen scheidt."),
"quran_046": ("Waarbij zweert Allah aan het begin van soera At-Tur?", ["Bij de Berg (Tur)", "Bij de zon", "Bij de vijg", "Bij de nacht"], "«Bij de Berg! En bij een beschreven Boek…» (52:1-2): de Tur is de berg waar Musa de openbaring ontving."),
"quran_047": ("Wat betekent «An-Najm», de titel van soera 53?", ["De ster", "De maan", "De zon", "De dageraad"], "«Bij de ster wanneer zij ondergaat!» (53:1)."),
"quran_048": ("Wie daalt volgens soera Al-Qadr neer tijdens de Nacht van de Beschikking?", ["De engelen en de Geest (Jibril)", "De profeten", "De djinn", "De winden"], "«De engelen en de Geest dalen daarin neer met toestemming van hun Heer» (97:4)."),
"quran_049": ("Wat is de Koran volgens de Koran voor de gelovigen?", ["Een genezing en een genade", "Slechts een gedicht", "Een geschiedenisboek", "Een kalender"], "«Wij zenden van de Koran neer wat genezing en genade is voor de gelovigen» (17:82)."),
"quran_050": ("Welke uitdaging stelt de Koran aan wie twijfelt aan zijn goddelijke oorsprong?", ["Breng één soera voort die erop lijkt", "Reciteer de hele Koran uit het hoofd", "Vertaal de Koran", "Bouw een moskee"], "«Als jullie twijfelen aan wat Wij hebben neergezonden, breng dan een soera voort die erop lijkt» (2:23)."),
"quran_051": ("Welke soera wordt «Umm al-Qur'an» (de Moeder van de Koran) genoemd?", ["Al-Fatiha", "Al-Baqara", "Ya-Sin", "Al-Ikhlas"], "De Profeet ﷺ zei: «Umm al-Qur'an is de zeven vaak herhaalde verzen en de grootse Koran.»"),
"quran_052": ("Wat is een «Mekkaanse» soera?", ["Een soera geopenbaard vóór de Hijra", "Een soera geopenbaard in Medina", "Een soera over de Ka'ba", "Een zeer korte soera"], "Geleerden delen soera's in naar periode: vóór de migratie naar Medina (Mekkaans) of daarna (Medinees)."),
"quran_053": ("Hoeveel soera's beginnen met de letters «Alif, Lam, Mim»?", ["Zes", "Twee", "Tien", "Eén"], "Al-Baqara, Al 'Imran, Al-'Ankabut, Ar-Rum, Luqman en As-Sajda openen met «Alif, Lam, Mim»."),
"quran_054": ("Hoe heten de losse letters waarmee sommige soera's openen (Alif Lam Mim, Ya Sin, Qaf…)?", ["De afgescheiden letters (al-huruf al-muqatta'a)", "De afgeschafte verzen", "De zonneletters", "De tajwid-letters"], "Negenentwintig soera's openen met deze letters, waarvan alleen Allah de volledige betekenis kent."),
"quran_055": ("Welke soera is genoemd naar de Profeet Muhammad ﷺ?", ["Soera 47, Muhammad", "Soera 1, Al-Fatiha", "Soera 36, Ya-Sin", "Soera 112, Al-Ikhlas"], "Soera 47 heet «Muhammad»; zij noemt zijn naam in vers 2."),
"quran_056": ("Wat is het eerste advies van Luqman aan zijn zoon, geciteerd in de Koran?", ["Ken niets als deelgenoot toe aan Allah", "Bestudeer de sterren", "Word koopman", "Reis ver weg"], "«O mijn zoon, ken Allah geen deelgenoten toe; voorwaar, het toekennen van deelgenoten is een groot onrecht» (31:13)."),
"quran_057": ("Onder welke andere naam is soera At-Tawba bekend?", ["Bara'a (de Verklaring van ontheffing)", "An-Nur", "Al-Anfal", "Al-Fath"], "Haar eerste woord is «Bara'a»: een verklaring van ontheffing van Allah en Zijn Boodschapper tegenover de afgodendienaars (9:1)."),
"quran_058": ("Welke soera begint met de twee letters «Ya, Sin»?", ["Ya-Sin (soera 36)", "Ta-Ha", "Qaf", "Sad"], "Soera 36 opent met «Ya-Sin. Bij de wijze Koran!»"),
"quran_059": ("Wat betekent «Al-Mulk», de titel van soera 67?", ["De Heerschappij / het Koninkrijk", "Het Licht", "De Reis", "De Overwinning"], "«Gezegend is Hij in Wiens hand de Heerschappij (al-Mulk) is» (67:1)."),
"quran_060": ("Wat is de laatste soera van de Koran?", ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Fatiha"], "An-Nas («De Mensen»), soera 114, sluit de Koran af: «Zeg: ik zoek toevlucht bij de Heer van de mensen»."),
"quran_061": ("Hoe begint soera Al-Falaq?", ["«Zeg: ik zoek toevlucht bij de Heer van de dageraad»", "«Zeg: Hij is Allah, Eén»", "«Bij de tijd!»", "«Lof zij Allah»"], "«Qul a'udhu bi-rabbi-l-falaq» (113:1): Al-Falaq betekent de dageraad."),
"quran_062": ("Welke twee heuvels noemt de Koran onder de «tekenen van Allah»?", ["As-Safa en Al-Marwa", "Uhud en Thawr", "'Arafat en Mina", "Hira' en Abu Qubays"], "«As-Safa en Al-Marwa behoren tot de tekenen van Allah» (2:158): de sa'y van de bedevaart wordt ertussen gelopen."),
"quran_063": ("Wie is de enige vrouw die bij naam wordt genoemd in de Koran?", ["Maryam", "Khadija", "Asiya", "Hajar"], "Maryam, moeder van 'Isa, wordt in verschillende soera's genoemd, en een hele soera draagt haar naam."),
"quran_064": ("Wie is de enige metgezel van de Profeet ﷺ die in de Koran bij naam wordt genoemd?", ["Zayd ibn Haritha", "Abu Bakr", "'Umar", "'Ali"], "«Toen Zayd zijn band met haar had beëindigd…» (33:37): Zayd, de vrijgelaten slaaf van de Profeet, is de enige metgezel die genoemd wordt."),
"quran_065": ("Wie waren Harut en Marut, genoemd in soera Al-Baqara?", ["Twee engelen gezonden naar Babylon", "Twee profeten", "Twee koningen van Egypte", "Twee metgezellen"], "«…wat werd neergezonden aan de twee engelen Harut en Marut in Babylon» (2:102): zij waarschuwden dat tovenarij een beproeving was."),
"quran_066": ("Wie is volgens de Koran het edelst in de ogen van Allah?", ["De meest godvrezende", "De rijkste", "De sterkste", "De beroemdste"], "«De edelste van jullie in de ogen van Allah is de meest godvrezende» (49:13)."),
"quran_067": ("Waarnaar verwijst «Al-Waqi'a», de titel van soera 56?", ["Naar de onvermijdelijke Gebeurtenis (de Dag der Opstanding)", "Naar de karavaan", "Naar de mier", "Naar de nachtreis"], "«Wanneer de Gebeurtenis plaatsvindt…» (56:1): de soera beschrijft de drie groepen van de Laatste Dag."),
"quran_068": ("Bij welk voorwerp zweert Allah aan het begin van soera Al-Qalam?", ["Bij de pen", "Bij het zwaard", "Bij de weegschaal", "Bij de lamp"], "«Nun. Bij de pen en wat zij schrijven!» (68:1)."),
"quran_069": ("Hoe opent soera Al-Fajr?", ["Met een eed bij de dageraad en tien nachten", "Met een eed bij de vijg", "Met een verhaal over Yusuf", "Met alleen de basmala"], "«Bij de dageraad! En bij de tien nachten!» (89:1-2)."),
"quran_070": ("Bij welk hemellichaam zweert Allah aan het begin van soera Ash-Shams?", ["De zon", "Alleen de maan", "De sterren", "De planeten"], "«Bij de zon en haar schittering!» (91:1); Ash-Shams betekent «de zon»."),
"quran_071": ("Welke soera opent met: «Is er voor de mens een tijdsperiode geweest waarin hij niets noemenswaardigs was?»", ["Al-Insan (soera 76)", "Al-Kahf", "Al-Hajj", "Al-Fatiha"], "Al-Insan («De Mens»), ook Ad-Dahr genoemd, herinnert eraan dat de mens niets was vóór zijn schepping (76:1)."),
"quran_072": ("Waarvoor heeft Allah de Koran volgens de Koran gemakkelijk gemaakt?", ["Voor de herinnering en het memoriseren", "Voor de handel", "Voor de vertaling", "Om te vergeten"], "«Wij hebben de Koran gemakkelijk gemaakt om te gedenken; is er iemand die er lering uit trekt?» (54:17), vier keer herhaald in de soera."),
"quran_073": ("Welk teken noemt soera Al-Qamar in haar allereerste vers?", ["De maan spleet", "De zon doofde", "De zee ging open", "De berg sprak"], "«Het Uur is nabij gekomen en de maan is gespleten» (54:1): een teken getoond aan de Mekkanen."),
"quran_074": ("Waarom werd de Koran geleidelijk geopenbaard en niet in één keer, volgens de Koran zelf?", ["Om het hart van de Profeet ﷺ te versterken", "Omdat hij te lang was", "Om hem voor vijanden te verbergen", "Vanwege reizen"], "«Zo, opdat Wij jouw hart daarmee versterken, en Wij hebben hem met zorgvuldige recitatie gereciteerd» (25:32)."),
"quran_075": ("Welke soera's reciteerde de Profeet ﷺ elke nacht in zijn handen voor het slapengaan, volgens 'A'isha?", ["Al-Ikhlas, Al-Falaq en An-Nas", "Al-Fatiha en Al-Baqara", "Ya-Sin en Al-Mulk", "Al-Kahf en Maryam"], "Hij blies in zijn handen terwijl hij de drie «Qul»-soera's reciteerde, en streek er dan drie keer mee over zijn lichaam."),
"quran_076": ("Hoe heet de neerwerping die wordt verricht bij het reciteren van bepaalde verzen van de Koran?", ["De neerwerping van de recitatie (sujud at-tilawa)", "De neerwerping van de vergetelheid", "De neerwerping van dankbaarheid", "De ruku'"], "De Koran bevat neerwerpingsverzen, zoals het laatste vers van Al-'Alaq: «werp je neer en kom nader» (96:19)."),
"quran_077": ("Hoe heet de wetenschap van de regels voor het correct uitspreken van de Koran?", ["Tajwid", "Tafsir", "Fiqh", "Sira"], "Tajwid leert hoe elke letter vanuit haar articulatiepunt wordt uitgesproken, met haar eigenschappen."),
"quran_078": ("Hoe heet iemand die de hele Koran uit het hoofd heeft geleerd?", ["Een hafiz", "Een imam", "Een muezzin", "Een mufti"], "Hafiz betekent «degene die bewaakt»: hij draagt de hele Koran in zijn geheugen."),
"quran_079": ("Hoe heet het geschreven exemplaar van de Koran?", ["Een mushaf", "Een hadith", "Een juz'", "Een minbar"], "De mushaf is de Koran verzameld tussen twee kaften; een juz' is een van zijn dertig delen."),
"quran_080": ("In welke soera komt de basmala twee keer voor?", ["An-Naml", "Al-Fatiha", "At-Tawba", "Al-Baqara"], "Behalve in haar opening citeert An-Naml de basmala aan het begin van de brief van Sulayman aan de koningin van Saba' (27:30)."),
}
